// ---------------------------------------------------------- footprints
var bldg;
if (SOURCE === 'VIDA') {
  bldg = ee.FeatureCollection('projects/sat-io/open-datasets/VIDA_COMBINED/SAU')
           .filterBounds(URBAN_BOX);
} else {
  // Microsoft asset name may use a space or underscore; try both if needed
  bldg = ee.FeatureCollection('projects/sat-io/open-datasets/MSBuildings/Saudi_Arabia')
           .filterBounds(URBAN_BOX);
}
// area attribute: VIDA has area_in_meters; for MS compute it
bldg = bldg.map(function (f) {
  var a = ee.Algorithms.If(f.propertyNames().contains('area_in_meters'),
                           f.get('area_in_meters'), f.geometry().area(1));
  return f.set('a', a);
});

print('Buildings in the urban box:', bldg.size());
print('First building:', bldg.first());
Map.centerObject(URBAN_BOX, 11);
Map.addLayer(ZONES, {color: 'blue'}, 'Residential zones');
Map.addLayer(bldg, {color: 'red'}, 'Building footprints', false);

// ---------------------------------------------------------- per-zone table
var small  = ee.Filter.lt('a', 100);
var large  = ee.Filter.gte('a', 1000);
var medium = ee.Filter.and(ee.Filter.gte('a', 100), ee.Filter.lt('a', 1000));

var table = ZONES.map(function (z) {
  var b = bldg.filterBounds(z.geometry());
  var roof = b.aggregate_sum('a');
  var vida = b.filter(ee.Filter.eq('bf_source', 'google'));
  return z.set({
    n_bldg: b.size(),
    roof_m2: roof,
    mean_m2: b.aggregate_mean('a'),
    n_small: b.filter(small).size(),
    n_medium: b.filter(medium).size(),
    n_large: b.filter(large).size(),
    roof_large_m2: b.filter(large).aggregate_sum('a'),
    n_google: vida.size(),
    zone_area_m2: z.geometry().area(1)
  });
});

Export.table.toDrive({
  collection: table, description: 'Najran_buildings_per_zone',
  folder: DRIVE_FOLDER, fileFormat: 'CSV',
  selectors: ['zone_id', 'n_bldg', 'roof_m2', 'mean_m2', 'n_small', 'n_medium',
              'n_large', 'roof_large_m2', 'n_google', 'zone_area_m2']
});

// ---------------------------------------------------------- building fraction raster (30 m)
var frac = ee.Image(0).byte().paint(bldg, 1)
  .reproject({crs: CRS, scale: 5})
  .reduceResolution({reducer: ee.Reducer.mean(), maxPixels: 64})
  .reproject({crs: CRS, scale: 30})
  .rename('bldg_frac').toFloat();

Export.image.toDrive({
  image: frac, description: 'Najran_buildings_fraction_30m',
  folder: DRIVE_FOLDER, region: URBAN_BOX, crs: CRS, crsTransform: GRID, maxPixels: 1e9
});

// ---------------------------------------------------------- terrain (for growth scenarios)
var dem = ee.Image('USGS/SRTMGL1_003');
var terrain = dem.rename('elev').addBands(ee.Terrain.slope(dem).rename('slope')).toFloat();
Export.image.toDrive({
  image: terrain, description: 'Najran_terrain_30m',
  folder: DRIVE_FOLDER, region: AOI, crs: CRS, crsTransform: GRID, maxPixels: 1e9
});
